BEGIN;

-- COL-132: stable catalog identities and source provenance. No schedules or
-- published requirements are inferred from administrative source material.
CREATE TABLE public.operation_activities (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id uuid NOT NULL REFERENCES public.organizations(id),
  facility_id uuid REFERENCES public.facilities(id),
  activity_key text NOT NULL CHECK (length(btrim(activity_key)) > 0),
  name text NOT NULL CHECK (length(btrim(name)) > 0),
  activity_kind text CHECK (activity_kind IN ('attestation','structured_observation','record_review','event_checklist','data_field','linked_domain_action')),
  subject_kind text CHECK (subject_kind IN ('facility','resident','employee','asset')),
  origin text NOT NULL CHECK (origin IN ('legacy_template','admin_log')),
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (organization_id, activity_key),
  UNIQUE (organization_id, id)
);
CREATE TABLE public.operation_activity_source_items (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id uuid NOT NULL REFERENCES public.organizations(id),
  source_item_id text NOT NULL CHECK (source_item_id ~ '^AL-[DWMAQYNCEH][0-9]{2}$'),
  intake_version text NOT NULL,
  source_file text NOT NULL,
  source_sha256 text NOT NULL CHECK (source_sha256 ~ '^[0-9a-f]{64}$'),
  source_payload jsonb NOT NULL CHECK (jsonb_typeof(source_payload) = 'object'),
  status text NOT NULL DEFAULT 'draft' CHECK (status = 'draft'),
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (organization_id, source_item_id, intake_version),
  UNIQUE (organization_id, id)
);
CREATE TABLE public.operation_activity_source_mappings (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id uuid NOT NULL REFERENCES public.organizations(id),
  source_item_id uuid NOT NULL,
  activity_id uuid NOT NULL,
  UNIQUE (source_item_id, activity_id),
  FOREIGN KEY (organization_id, source_item_id) REFERENCES public.operation_activity_source_items(organization_id,id),
  FOREIGN KEY (organization_id, activity_id) REFERENCES public.operation_activities(organization_id,id)
);
-- This registry stores references, never copies a resident/employee/asset master.
-- No client grants or SELECT policy until COL-133 defines subject authorization.
CREATE TABLE public.operation_activity_subjects (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id uuid NOT NULL REFERENCES public.organizations(id),
  facility_id uuid NOT NULL REFERENCES public.facilities(id),
  subject_kind text NOT NULL CHECK (subject_kind IN ('facility','resident','employee','asset')),
  resident_id uuid REFERENCES public.residents(id),
  employee_id uuid REFERENCES public.staff(id),
  asset_id uuid REFERENCES public.facility_assets(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK ((subject_kind='facility' AND num_nonnulls(resident_id,employee_id,asset_id)=0)
    OR (subject_kind='resident' AND resident_id IS NOT NULL AND num_nonnulls(resident_id,employee_id,asset_id)=1)
    OR (subject_kind='employee' AND employee_id IS NOT NULL AND num_nonnulls(resident_id,employee_id,asset_id)=1)
    OR (subject_kind='asset' AND asset_id IS NOT NULL AND num_nonnulls(resident_id,employee_id,asset_id)=1))
);
CREATE UNIQUE INDEX operation_subject_facility_unique ON public.operation_activity_subjects(facility_id) WHERE subject_kind='facility';
CREATE UNIQUE INDEX operation_subject_resident_unique ON public.operation_activity_subjects(facility_id,resident_id) WHERE subject_kind='resident';
CREATE UNIQUE INDEX operation_subject_employee_unique ON public.operation_activity_subjects(facility_id,employee_id) WHERE subject_kind='employee';
CREATE UNIQUE INDEX operation_subject_asset_unique ON public.operation_activity_subjects(facility_id,asset_id) WHERE subject_kind='asset';
ALTER TABLE public.operation_activities ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.operation_activity_source_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.operation_activity_source_mappings ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.operation_activity_subjects ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.operation_activities, public.operation_activity_source_items,
  public.operation_activity_source_mappings, public.operation_activity_subjects FROM PUBLIC,anon,authenticated;
REVOKE ALL ON public.operation_activity_subjects FROM service_role;
GRANT SELECT ON public.operation_activities, public.operation_activity_source_items,
  public.operation_activity_source_mappings TO authenticated;
CREATE POLICY operation_activity_sources_read ON public.operation_activity_source_items FOR SELECT TO authenticated USING (
  organization_id=haven.organization_id()
);
CREATE POLICY operation_activity_mappings_read ON public.operation_activity_source_mappings FOR SELECT TO authenticated USING (
  organization_id=haven.organization_id() AND EXISTS (
    SELECT 1 FROM public.operation_activities a WHERE a.id=activity_id AND a.organization_id=operation_activity_source_mappings.organization_id)
);

CREATE FUNCTION haven.guard_operation_source_provenance() RETURNS trigger
LANGUAGE plpgsql SET search_path='' AS $$
BEGIN
  RAISE EXCEPTION 'Activity source provenance is immutable' USING ERRCODE='23514';
END $$;
REVOKE ALL ON FUNCTION haven.guard_operation_source_provenance() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER operation_source_provenance BEFORE UPDATE OR DELETE ON public.operation_activity_source_items
  FOR EACH ROW EXECUTE FUNCTION haven.guard_operation_source_provenance();
CREATE TRIGGER operation_source_mapping_provenance BEFORE UPDATE OR DELETE ON public.operation_activity_source_mappings
  FOR EACH ROW EXECUTE FUNCTION haven.guard_operation_source_provenance();

-- A trigger-only private validator. Its generic error deliberately discloses no
-- protected subject existence; it is not an exposed privileged RPC.
CREATE FUNCTION haven.validate_operation_activity_subject() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'Activity subject references are immutable' USING ERRCODE='23514';
  END IF;
  PERFORM 1 FROM public.facilities WHERE id=NEW.facility_id AND organization_id=NEW.organization_id AND deleted_at IS NULL FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Invalid activity subject scope' USING ERRCODE='23514'; END IF;
  IF NEW.subject_kind='resident' THEN
    PERFORM 1 FROM public.residents WHERE id=NEW.resident_id AND organization_id=NEW.organization_id AND facility_id=NEW.facility_id AND deleted_at IS NULL FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Invalid activity subject scope' USING ERRCODE='23514'; END IF;
  ELSIF NEW.subject_kind='employee' THEN
    PERFORM 1 FROM public.staff WHERE id=NEW.employee_id AND organization_id=NEW.organization_id AND facility_id=NEW.facility_id AND deleted_at IS NULL FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Invalid activity subject scope' USING ERRCODE='23514'; END IF;
  ELSIF NEW.subject_kind='asset' THEN
    PERFORM 1 FROM public.facility_assets WHERE id=NEW.asset_id AND organization_id=NEW.organization_id AND facility_id=NEW.facility_id AND deleted_at IS NULL FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Invalid activity subject scope' USING ERRCODE='23514'; END IF;
  END IF;
  RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION haven.validate_operation_activity_subject() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER operation_activity_subject_scope BEFORE INSERT OR UPDATE OR DELETE ON public.operation_activity_subjects
  FOR EACH ROW EXECUTE FUNCTION haven.validate_operation_activity_subject();

CREATE FUNCTION haven.guard_operation_activity_identity() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Activity identity is immutable' USING ERRCODE='23514'; END IF;
  IF TG_OP='UPDATE' AND (NEW.id,NEW.organization_id,NEW.facility_id,NEW.activity_key,NEW.origin,NEW.activity_kind,NEW.subject_kind)
    IS DISTINCT FROM (OLD.id,OLD.organization_id,OLD.facility_id,OLD.activity_key,OLD.origin,OLD.activity_kind,OLD.subject_kind) THEN
    RAISE EXCEPTION 'Activity identity is immutable' USING ERRCODE='23514';
  END IF;
  IF NEW.facility_id IS NOT NULL THEN
    PERFORM 1 FROM public.facilities WHERE id=NEW.facility_id AND organization_id=NEW.organization_id FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Invalid activity facility scope' USING ERRCODE='23514'; END IF;
  END IF;
  RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION haven.guard_operation_activity_identity() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER operation_activity_identity BEFORE INSERT OR UPDATE OR DELETE ON public.operation_activities
  FOR EACH ROW EXECUTE FUNCTION haven.guard_operation_activity_identity();

-- Row-level guards do not fire for TRUNCATE; catalog history is never bulk-erased.
CREATE FUNCTION haven.guard_operation_catalog_truncate() RETURNS trigger
LANGUAGE plpgsql SET search_path='' AS $$
BEGIN RAISE EXCEPTION 'Activity catalog history cannot be truncated' USING ERRCODE='23514'; END $$;
REVOKE ALL ON FUNCTION haven.guard_operation_catalog_truncate() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER operation_activities_no_truncate BEFORE TRUNCATE ON public.operation_activities
  FOR EACH STATEMENT EXECUTE FUNCTION haven.guard_operation_catalog_truncate();
CREATE TRIGGER operation_source_items_no_truncate BEFORE TRUNCATE ON public.operation_activity_source_items
  FOR EACH STATEMENT EXECUTE FUNCTION haven.guard_operation_catalog_truncate();
CREATE TRIGGER operation_source_mappings_no_truncate BEFORE TRUNCATE ON public.operation_activity_source_mappings
  FOR EACH STATEMENT EXECUTE FUNCTION haven.guard_operation_catalog_truncate();
CREATE TRIGGER operation_activity_subjects_no_truncate BEFORE TRUNCATE ON public.operation_activity_subjects
  FOR EACH STATEMENT EXECUTE FUNCTION haven.guard_operation_catalog_truncate();

ALTER TABLE public.operation_task_templates ADD COLUMN activity_id uuid REFERENCES public.operation_activities(id);
ALTER TABLE public.operation_task_instances ADD COLUMN activity_id uuid REFERENCES public.operation_activities(id);
CREATE POLICY operation_activities_read ON public.operation_activities FOR SELECT TO authenticated USING (
  organization_id=haven.organization_id() AND (facility_id IS NULL OR haven.has_facility_access(facility_id))
  AND (origin='admin_log' OR EXISTS (
    SELECT 1 FROM public.operation_task_templates t WHERE t.activity_id=operation_activities.id AND t.deleted_at IS NULL
  ))
);


-- Resolve only explicit previous_version_id lineage. Never infer a source match
-- from name/category, and abort atomically on invalid legacy tenant/site chains.
DO $$
DECLARE t public.operation_task_templates; ancestor public.operation_task_templates; seen uuid[]; root_id uuid;
BEGIN
  FOR t IN SELECT * FROM public.operation_task_templates ORDER BY id LOOP
    ancestor:=t; seen:=ARRAY[t.id];
    WHILE ancestor.previous_version_id IS NOT NULL LOOP
      IF ancestor.previous_version_id=ANY(seen) THEN
        RAISE EXCEPTION 'Cyclic operation template lineage: %',t.id USING ERRCODE='23514';
      END IF;
      SELECT * INTO STRICT ancestor FROM public.operation_task_templates WHERE id=ancestor.previous_version_id;
      IF ancestor.organization_id IS DISTINCT FROM t.organization_id OR ancestor.facility_id IS DISTINCT FROM t.facility_id THEN
        RAISE EXCEPTION 'Invalid operation template lineage scope: %',t.id USING ERRCODE='23514';
      END IF;
      seen:=array_append(seen,ancestor.id);
    END LOOP;
    root_id:=ancestor.id;
    INSERT INTO public.operation_activities(id,organization_id,facility_id,activity_key,name,origin)
      VALUES(root_id,t.organization_id,t.facility_id,'legacy-template:'||root_id,ancestor.name,'legacy_template')
      ON CONFLICT (id) DO NOTHING;
    UPDATE public.operation_task_templates SET activity_id=root_id WHERE id=t.id;
  END LOOP;
  IF EXISTS(SELECT 1 FROM public.operation_task_instances i JOIN public.operation_task_templates linked ON linked.id=i.template_id
    WHERE i.organization_id<>linked.organization_id OR (linked.facility_id IS NOT NULL AND i.facility_id<>linked.facility_id)) THEN
    RAISE EXCEPTION 'Invalid operation instance template scope' USING ERRCODE='23514';
  END IF;
  UPDATE public.operation_task_instances i SET activity_id=linked.activity_id FROM public.operation_task_templates linked WHERE linked.id=i.template_id;
END $$;
ALTER TABLE public.operation_task_templates ALTER COLUMN activity_id SET NOT NULL;
CREATE INDEX operation_templates_activity ON public.operation_task_templates(activity_id);
CREATE INDEX operation_instances_activity ON public.operation_task_instances(activity_id);

-- Legacy template writers still use their existing owner/org_admin RLS. This
-- trigger-only guard locks live authority after target/lineage waits before its
-- narrowly privileged catalog insert. Instance binding adds no blocking locks: the
-- referenced template identity is immutable and its foreign key pins existence.
CREATE FUNCTION haven.assert_operation_catalog_actor(p_org uuid,p_facility uuid,p_template boolean) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE actor record;
BEGIN
  IF auth.uid() IS NULL THEN RETURN; END IF;
  PERFORM 1 FROM public.user_facility_access WHERE user_id=auth.uid()
    AND organization_id=p_org AND facility_id=p_facility AND revoked_at IS NULL FOR SHARE;
  PERFORM 1 FROM public.user_profiles p JOIN auth.users u ON u.id=p.id
    JOIN auth.sessions s ON s.user_id=p.id AND s.id=nullif(auth.jwt()->>'session_id','')::uuid
    WHERE p.id=auth.uid() FOR SHARE OF p,u,s;
  SELECT * INTO actor FROM haven.current_authorized_actor();
  IF actor.actor_is_managed IS NOT TRUE OR actor.actor_organization_id IS DISTINCT FROM p_org
    OR (p_template AND actor.actor_app_role NOT IN ('owner','org_admin'))
    OR (p_facility IS NOT NULL AND NOT haven.has_facility_access(p_facility)) THEN
    RAISE EXCEPTION 'Operation catalog actor is no longer authorized' USING ERRCODE='42501';
  END IF;
END $$;
REVOKE ALL ON FUNCTION haven.assert_operation_catalog_actor(uuid,uuid,boolean) FROM PUBLIC,anon,authenticated;

CREATE FUNCTION haven.bind_operation_template_activity() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE parent public.operation_task_templates; activity public.operation_activities;
BEGIN
  IF TG_OP='UPDATE' THEN
    IF (NEW.id,NEW.organization_id,NEW.facility_id,NEW.previous_version_id,NEW.activity_id)
      IS DISTINCT FROM (OLD.id,OLD.organization_id,OLD.facility_id,OLD.previous_version_id,OLD.activity_id) THEN
      RAISE EXCEPTION 'Operation template identity is immutable' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.facility_id IS NOT NULL THEN
    PERFORM 1 FROM public.facilities WHERE id=NEW.facility_id AND organization_id=NEW.organization_id AND deleted_at IS NULL FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Invalid operation template facility scope' USING ERRCODE='23514'; END IF;
  END IF;
  IF NEW.previous_version_id IS NOT NULL THEN
    SELECT * INTO parent FROM public.operation_task_templates WHERE id=NEW.previous_version_id FOR SHARE;
    IF NOT FOUND OR parent.organization_id IS DISTINCT FROM NEW.organization_id OR parent.facility_id IS DISTINCT FROM NEW.facility_id THEN
      RAISE EXCEPTION 'Invalid operation template lineage scope' USING ERRCODE='23514';
    END IF;
    IF NEW.activity_id IS NOT NULL AND NEW.activity_id<>parent.activity_id THEN
      RAISE EXCEPTION 'Operation template revision must retain activity' USING ERRCODE='23514';
    END IF;
    NEW.activity_id:=parent.activity_id;
  ELSIF NEW.activity_id IS NULL THEN
    PERFORM haven.assert_operation_catalog_actor(NEW.organization_id,NEW.facility_id,true);
    INSERT INTO public.operation_activities(organization_id,facility_id,activity_key,name,origin)
      VALUES(NEW.organization_id,NEW.facility_id,'legacy-template:'||NEW.id,NEW.name,'legacy_template') RETURNING id INTO NEW.activity_id;
  ELSIF (nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role') IN ('anon','authenticated')
    AND current_setting('haven.operation_catalog_bind',true) IS DISTINCT FROM 'approved' THEN
    -- A client request (this trigger runs as its definer, so the JWT role claim is
    -- the request identity) receives its own legacy identity on a root insert. It
    -- can never adopt a catalog activity or another lineage. Only an approved
    -- command that sets haven.operation_catalog_bind for its transaction may bind.
    RAISE EXCEPTION 'Operation template cannot choose a stable activity' USING ERRCODE='23514';
  END IF;
  SELECT * INTO activity FROM public.operation_activities WHERE id=NEW.activity_id FOR SHARE;
  IF NOT FOUND OR activity.organization_id IS DISTINCT FROM NEW.organization_id
    OR (activity.facility_id IS NOT NULL AND activity.facility_id IS DISTINCT FROM NEW.facility_id) THEN
    RAISE EXCEPTION 'Invalid operation template activity scope' USING ERRCODE='23514';
  END IF;
  PERFORM haven.assert_operation_catalog_actor(NEW.organization_id,NEW.facility_id,true);
  RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION haven.bind_operation_template_activity() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER operation_template_activity BEFORE INSERT OR UPDATE ON public.operation_task_templates
  FOR EACH ROW EXECUTE FUNCTION haven.bind_operation_template_activity();

-- Identity reads below deliberately avoid FOR SHARE: no new lock wait may be
-- introduced after existing service RPC actor checks. Only immutable fields are read.
CREATE FUNCTION haven.bind_operation_instance_activity() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE template public.operation_task_templates;
BEGIN
  IF TG_OP='UPDATE' THEN
    IF (NEW.id,NEW.organization_id,NEW.facility_id,NEW.template_id,NEW.activity_id)
      IS DISTINCT FROM (OLD.id,OLD.organization_id,OLD.facility_id,OLD.template_id,OLD.activity_id) THEN
      RAISE EXCEPTION 'Operation instance identity is immutable' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
  END IF;
  PERFORM 1 FROM public.facilities WHERE id=NEW.facility_id AND organization_id=NEW.organization_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'Invalid operation instance facility scope' USING ERRCODE='23514'; END IF;
  IF NEW.template_id IS NULL THEN
    IF NEW.activity_id IS NOT NULL THEN RAISE EXCEPTION 'Unreconciled operation instance activity' USING ERRCODE='23514'; END IF;
    RETURN NEW;
  END IF;
  SELECT * INTO template FROM public.operation_task_templates WHERE id=NEW.template_id;
  IF NOT FOUND OR template.organization_id IS DISTINCT FROM NEW.organization_id
    OR (template.facility_id IS NOT NULL AND template.facility_id IS DISTINCT FROM NEW.facility_id) THEN
    RAISE EXCEPTION 'Invalid operation instance template scope' USING ERRCODE='23514';
  END IF;
  IF NEW.activity_id IS NOT NULL AND NEW.activity_id<>template.activity_id THEN
    RAISE EXCEPTION 'Operation instance must retain template activity' USING ERRCODE='23514';
  END IF;
  NEW.activity_id:=template.activity_id;
  RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION haven.bind_operation_instance_activity() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER operation_instance_activity BEFORE INSERT OR UPDATE ON public.operation_task_instances
  FOR EACH ROW EXECUTE FUNCTION haven.bind_operation_instance_activity();

COMMENT ON COLUMN public.operation_task_instances.activity_id IS
  'Stable activity at creation. NULL on legacy template-less instances means unreconciled, never inferred from a name.';
COMMENT ON TABLE public.operation_activity_subjects IS
  'Internal validated subject references at registration site. No client access until COL-133 subject authorization; no completion or schedule is implied.';
COMMENT ON TABLE public.operation_activity_source_items IS
  'Immutable intake provenance retained as draft source material, not a published requirement or operating approval.';

