supervised competencies","disposition":"mapped","kind":"data_field","subjectKind":"employee","confirmationReason":null,"components":[{"key":"hfo-al-e11-01","id":"e0df530b-a333-4654-8013-27e34beb15a5","label":"Med Tech 6 hour course completion date","kind":"data_field","subjectKind":"employee"}],"status":"draft","approvedRule":null,"effortMinutes":null},{"sourceId":"AL-E12","sourceSheet":"Employee File","sourceCell":"M1","sourceText":"New Hire Inservices Complete","sourceTimingEvidence":"New-hire completion; interview says pre-service before floor and company 30-day policy; exact course matrix unapproved.","questionIds":["Q20"],"proposedCapture":"Applicable initial course set, evidence and before-floor/30-day distinctions","disposition":"mapped","kind":"event_checklist","subjectKind":"employee","confirmationReason":null,"components":[{"key":"hfo-al-e12-01","id":"7b4a5f97-6cde-40c9-8704-4b4432065c90","label":"Record new-hire inservice completion","kind":"event_checklist","subjectKind":"employee"}],"status":"draft","approvedRule":null,"effortMinutes":null},{"sourceId":"AL-E13","sourceSheet":"Employee File","sourceCell":"N1","sourceText":"Update AHCA Roster Website","sourceTimingEvidence":"Employee roster update event; deadline unknown; separate weekly audit.","questionIds":["Q21"],"proposedCapture":"Employee event, roster submission and accepted confirmation","disposition":"mapped","kind":"linked_domain_action","subjectKind":"employee","confirmationReason":null,"components":[{"key":"hfo-al-e13-01","id":"edf59191-1dab-4105-9fa5-07f5ebedb285","label":"Record employee AHCA roster update","kind":"linked_domain_action","subjectKind":"employee"}],"status":"draft","approvedRule":null,"effortMinutes":null},{"sourceId":"AL-E14","sourceSheet":"Employee File","sourceCell":"O1","sourceText":"Manager 12 Hour Update Bianually","sourceTimingEvidence":"Cell says Bianually; 12 hours is duration; interval ambiguous.","questionIds":["Q07","Q20"],"proposedCapture":"12-hour manager training evidence; ambiguous interval unresolved","disposition":"mapped","kind":"linked_domain_action","subjectKind":"employee","confirmationReason":null,"components":[{"key":"hfo-al-e14-01","id":"6b08d2b7-6c54-48e8-945d-c161116f5470","label":"Record Manager 12 Hour Update","kind":"linked_domain_action","subjectKind":"employee"}],"status":"draft","approvedRule":null,"effortMinutes":null},{"sourceId":"AL-H01","sourceSheet":"Mental Health Facilities","sourceCell":"B1","sourceText":"Community Support Plan","sourceTimingEvidence":"Monthly grid; interview describes six-month external plans. Review versus renewal/document scope unresolved.","questionIds":["Q08","Q24"],"proposedCapture":"Separate applicable external plan types, resident, caseworker, signatures, dates and monthly review","disposition":"needs_confirmation","kind":"record_review","subjectKind":"resident","confirmationReason":"Q08/Q24: confirm applicable external plan types and distinguish review from renewal.","components":[{"key":"hfo-al-h01-01","id":"2e061e2d-05e2-431b-b371-6a8bdf17f3f6","label":"Community Support Plan","kind":"record_review","subjectKind":"resident"}],"status":"draft","approvedRule":null,"effortMinutes":null}]}'::jsonb;
  v_entry jsonb;
  v_component jsonb;
  v_source uuid;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.organizations WHERE id = v_org) THEN
    RAISE EXCEPTION 'COL organization required for the reviewed Admin Log catalog';
  END IF;
  FOR v_entry IN SELECT value FROM jsonb_array_elements(v_catalog->'entries') LOOP
    v_source := md5(v_org::text || ':' || (v_catalog->>'catalogKey') || ':' || (v_entry->>'sourceId'))::uuid;
    INSERT INTO public.operation_activity_source_items
      (id, organization_id, source_item_id, intake_version, source_file, source_sha256, source_payload, status)
    VALUES (v_source, v_org, v_entry->>'sourceId', v_catalog->>'catalogKey',
      v_catalog->'source'->>'name', v_catalog->'source'->>'sha256', v_entry, 'draft');
    FOR v_component IN SELECT value FROM jsonb_array_elements(v_entry->'components') LOOP
      INSERT INTO public.operation_activities
        (id, organization_id, activity_key, name, activity_kind, subject_kind, origin)
      VALUES ((v_component->>'id')::uuid, v_org, v_component->>'key',
        v_component->>'label', v_component->>'kind', v_component->>'subjectKind', 'admin_log');
      INSERT INTO public.operation_activity_source_mappings (organization_id, source_item_id, activity_id)
      VALUES (v_org, v_source, (v_component->>'id')::uuid);
    END LOOP;
  END LOOP;
END;
$hfo_seed$;
